-- VEXONYX foundation v3.0
-- Supabase managed storage schema is reserved; VEXONYX metadata uses artifacts.
create extension if not exists vector with schema extensions;
create extension if not exists pg_trgm with schema extensions;
create schema if not exists app; create schema if not exists launch; create schema if not exists ai; create schema if not exists security; create schema if not exists artifacts; create schema if not exists reports; create schema if not exists usage; create schema if not exists billing; create schema if not exists operations; create schema if not exists audit;
revoke all on schema operations from public, anon, authenticated; revoke all on schema audit from public, anon, authenticated;
do $$ begin create type app.organization_role as enum ('organization_owner','organization_admin','member','viewer'); exception when duplicate_object then null; end $$;
do $$ begin create type app.project_status as enum ('active','archived'); exception when duplicate_object then null; end $$;
do $$ begin create type security.engagement_type as enum ('web_application','api','infrastructure','cloud','code_review','general_security_assessment'); exception when duplicate_object then null; end $$;
do $$ begin create type security.scope_type as enum ('domain','subdomain','ip','cidr','application','repository','cloud_resource'); exception when duplicate_object then null; end $$;
do $$ begin create type security.authorization_status as enum ('draft','pending_review','active','expired','revoked','rejected'); exception when duplicate_object then null; end $$;
do $$ begin create type security.finding_status as enum ('potential','reviewing','validated','reported','remediated','verified','false_positive','duplicate','accepted_risk'); exception when duplicate_object then null; end $$;
do $$ begin create type security.severity as enum ('critical','high','medium','low','informational'); exception when duplicate_object then null; end $$;
do $$ begin create type artifacts.file_status as enum ('quarantined','scanning','safe_for_processing','blocked','processing','ready','failed'); exception when duplicate_object then null; end $$;
do $$ begin create type ai.agent_run_state as enum ('QUEUED','PLANNING','CONTEXT_LOADING','MODEL_RUNNING','TOOL_REQUESTED','SCOPE_VALIDATION','WAITING_FOR_APPROVAL','TOOL_RUNNING','OBSERVATION','VALIDATING','WAITING_FOR_USER','PAUSED_BUDGET_LIMIT','COMPLETED','FAILED','CANCELLED'); exception when duplicate_object then null; end $$;
do $$ begin create type operations.incident_mode as enum ('normal','degraded','maintenance','security_lockdown'); exception when duplicate_object then null; end $$;
create table app.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,avatar_url text,timezone text not null default 'UTC',is_superadmin boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table app.organizations(id uuid primary key default gen_random_uuid(),name text not null check(char_length(name) between 2 and 120),slug text not null unique check(slug ~ '^[a-z0-9][a-z0-9-]{1,62}[a-z0-9]$'),created_by uuid not null references auth.users(id),status text not null default 'active' check(status in ('active','paused','archived')),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table app.organization_members(organization_id uuid not null references app.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role app.organization_role not null default 'member',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(organization_id,user_id));
create index organization_members_user_idx on app.organization_members(user_id,organization_id); create index organization_members_org_idx on app.organization_members(organization_id,role);
create or replace function operations.is_superadmin() returns boolean language sql stable security definer set search_path='' as $$select coalesce((select p.is_superadmin from app.profiles p where p.id=(select auth.uid())),false)$$;
create or replace function operations.is_org_member(org_id uuid) returns boolean language sql stable security definer set search_path='' as $$select org_id is not null and (operations.is_superadmin() or exists(select 1 from app.organization_members m where m.organization_id=org_id and m.user_id=(select auth.uid())))$$;
create or replace function operations.has_org_write(org_id uuid) returns boolean language sql stable security definer set search_path='' as $$select org_id is not null and (operations.is_superadmin() or exists(select 1 from app.organization_members m where m.organization_id=org_id and m.user_id=(select auth.uid()) and m.role in ('organization_owner','organization_admin','member')))$$;
create or replace function operations.has_org_admin(org_id uuid) returns boolean language sql stable security definer set search_path='' as $$select org_id is not null and (operations.is_superadmin() or exists(select 1 from app.organization_members m where m.organization_id=org_id and m.user_id=(select auth.uid()) and m.role in ('organization_owner','organization_admin')))$$;
create or replace function operations.try_uuid(value text) returns uuid language plpgsql immutable set search_path='' as $$begin return value::uuid; exception when others then return null; end$$;
revoke all on all functions in schema operations from public,anon,authenticated; grant usage on schema operations to authenticated; grant execute on function operations.is_superadmin() to authenticated; grant execute on function operations.is_org_member(uuid) to authenticated; grant execute on function operations.has_org_write(uuid) to authenticated; grant execute on function operations.has_org_admin(uuid) to authenticated; grant execute on function operations.try_uuid(text) to authenticated;
create or replace function operations.touch_updated_at() returns trigger language plpgsql set search_path='' as $$begin new.updated_at=now(); return new; end$$;
create or replace function operations.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into app.profiles(id,display_name) values(new.id,nullif(coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name'),'')) on conflict(id) do nothing; return new; end$$;
create or replace function operations.add_organization_owner() returns trigger language plpgsql security definer set search_path='' as $$begin insert into app.organization_members(organization_id,user_id,role) values(new.id,new.created_by,'organization_owner') on conflict(organization_id,user_id) do update set role='organization_owner',updated_at=now(); return new; end$$;
revoke all on function operations.handle_new_user() from public,anon,authenticated; revoke all on function operations.add_organization_owner() from public,anon,authenticated;
create trigger on_auth_user_created_vexonyx after insert on auth.users for each row execute function operations.handle_new_user(); create trigger organizations_add_owner after insert on app.organizations for each row execute function operations.add_organization_owner();
create table app.projects(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,created_by uuid not null references auth.users(id),name text not null check(char_length(name) between 1 and 160),description text,status app.project_status not null default 'active',visibility text not null default 'organization' check(visibility in ('private','organization')),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),archived_at timestamptz,deleted_at timestamptz); create index projects_org_updated_idx on app.projects(organization_id,updated_at desc) where deleted_at is null;
create table app.project_members(project_id uuid not null references app.projects(id) on delete cascade,organization_id uuid not null references app.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'member' check(role in ('owner','admin','member','viewer')),created_at timestamptz not null default now(),primary key(project_id,user_id)); create index project_members_org_user_idx on app.project_members(organization_id,user_id);
create table app.project_notes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,project_id uuid not null references app.projects(id) on delete cascade,created_by uuid not null references auth.users(id),content text not null default '',is_pinned boolean not null default false,revision integer not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz); create index project_notes_project_updated_idx on app.project_notes(project_id,updated_at desc) where deleted_at is null;
create table app.conversations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,project_id uuid references app.projects(id) on delete set null,user_id uuid not null references auth.users(id),title text not null default 'New conversation',status text not null default 'active' check(status in ('active','archived','deleted')),created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create index conversations_user_updated_idx on app.conversations(user_id,updated_at desc); create index conversations_project_updated_idx on app.conversations(project_id,updated_at desc);
create table app.messages(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,conversation_id uuid not null references app.conversations(id) on delete cascade,user_id uuid references auth.users(id),role text not null check(role in ('user','assistant','system','tool')),content jsonb not null default '{}'::jsonb,parent_message_id uuid references app.messages(id),created_at timestamptz not null default now()); create index messages_conversation_created_idx on app.messages(conversation_id,created_at);
